class DiscountStrategy:
    FIDELTY_THRESHOLD = 1000
    FIDELTY_DISCOUNT_RATE = 0.05
    BULK_QUANTITY_THRESHOLD = 20
    BULK_DISCOUNT_RATE = 0.1
    LARGE_ORDER_PANIER_SIZE = 10
    LARGE_ORDER_DISCOUNT_RATE = 0.07

    def __init__(self, customer, cart, promotion=None):
        self._customer = customer
        self._cart = cart
        self._promotion = promotion
        self._total = self.total()

    @property
    def customer(self):
        return self._customer

    @customer.setter
    def customer(self, customer):
        self._customer = customer

    @property
    def cart(self):
        return self._cart

    @cart.setter
    def cart(self, cart):
        self._cart = cart

    @property
    def promotion(self):
        return self._promotion

    @promotion.setter
    def promotion(self, promotion):
        self._promotion = promotion

    def total(self):
        self._total = sum(item['quantity'] * item['price'] for item in self._cart)
        return self._total

    def due(self):
        if self.promotion is None:
            return self.total()
        return self.total() - self.apply_promotion()

    def apply_promotion(self):
        return self.promotion(self)

    @staticmethod
    def FidelityPromo(order):
        FIDELTY_THRESHOLD = 1000
        FIDELTY_DISCOUNT_RATE = 0.05
        return order.total() * FIDELTY_DISCOUNT_RATE if order.customer['fidelity'] >= FIDELTY_THRESHOLD else 0

    @staticmethod
    def BulkItemPromo(order):
        BULK_QUANTITY_THRESHOLD = 20
        BULK_DISCOUNT_RATE = 0.1
        discount = 0
        for item in order.cart:
            if item['quantity'] >= BULK_QUANTITY_THRESHOLD:
                discount += item['quantity'] * item['price'] * BULK_DISCOUNT_RATE
        return discount

    @staticmethod
    def LargeOrderPromo(order):
        LARGE_ORDER_PANIER_SIZE = 10
        LARGE_ORDER_DISCOUNT_RATE = 0.07
        unique_items = order.count_unique_items()
        return order.total() * LARGE_ORDER_DISCOUNT_RATE if unique_items >= LARGE_ORDER_PANIER_SIZE else 0

    def count_unique_items(self):
        return len({item['product'] for item in self._cart})
